import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import { Activity, ArrowDownToLine, ArrowLeft, ArrowRight, Bell, CalendarDays, Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, Clock3, Command, Edit3, Ellipsis, GraduationCap, LayoutDashboard, ListTodo, Menu, MoreHorizontal, Plus, Repeat2, Search, Settings2, Sparkles, Trash2, X } from 'lucide-react'
import './style.css'

const weekdays = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom']
const months = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre']
const palette = ['#56d6fe', '#9a88ff', '#ffb866', '#62e5a4', '#ff78ad', '#f0e078', '#7db3ff', '#fd8e83']
const pad = n => String(n).padStart(2, '0')
const localISO = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
const todayISO = () => localISO(new Date())
const parseDate = s => new Date(`${String(s).slice(0, 10)}T12:00:00`)
const addDays = (d, n) => { const x = new Date(d); x.setDate(x.getDate() + n); return x }
const weekStart = d => addDays(d, -((d.getDay() + 6) % 7))
const sameDay = (a, b) => localISO(a) === localISO(b)
const formatDate = (s, options = { day: 'numeric', month: 'long' }) => s ? new Intl.DateTimeFormat('es-AR', options).format(parseDate(s)) : ''
const timeOf = s => String(s || '').includes('T') ? String(s).slice(11, 16) : ''
const startOfMonth = d => new Date(d.getFullYear(), d.getMonth(), 1)
const endOfMonth = d => new Date(d.getFullYear(), d.getMonth() + 1, 0)

async function api(path, options = {}) {
  const response = await fetch(`/agenda${path}`, {
    ...options,
    headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...options.headers }
  })
  if (!response.ok) {
    let detail = ''
    try { const payload = await response.json(); detail = typeof payload.detail === 'string' ? payload.detail : JSON.stringify(payload.detail) } catch {}
    throw new Error(detail || `Error ${response.status}`)
  }
  if (response.status === 204) return null
  return response.json()
}
const mutation = (path, method, body) => api(path, { method, ...(body !== undefined ? { body: JSON.stringify(body) } : {}) })

function IconButton({ icon: Icon, label, onClick, className = '', ...rest }) {
  return <button className={`icon-button ${className}`} type="button" aria-label={label} title={label} onClick={onClick} {...rest}><Icon size={18} strokeWidth={1.9} /></button>
}

function Tag({ color, children }) { return <span className="tag" style={{ '--tag': color || palette[0] }}><i />{children}</span> }

function Empty({ icon: Icon = Sparkles, title, description, action, onAction }) {
  return <div className="empty"><div className="empty-symbol"><Icon size={26} strokeWidth={1.5} /></div><h3>{title}</h3><p>{description}</p>{action && <button className="button button-primary" onClick={onAction}><Plus size={16} />{action}</button>}</div>
}

function Modal({ title, kicker, children, onClose, wide = false }) {
  useEffect(() => { const onKey = e => { if (e.key === 'Escape') onClose() }; window.addEventListener('keydown', onKey); return () => window.removeEventListener('keydown', onKey) }, [onClose])
  return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose() }}><div className={`modal ${wide ? 'modal-wide' : ''}`} role="dialog" aria-modal="true" aria-label={title}><div className="modal-head"><div><span className="eyebrow">{kicker || 'AGENDA / EDITAR'}</span><h2>{title}</h2></div><IconButton icon={X} label="Cerrar" onClick={onClose} /></div>{children}</div></div>
}

function Field({ label, children, hint }) { return <label className="field"><span>{label}</span>{children}{hint && <small>{hint}</small>}</label> }

function ColorPicker({ value, onChange }) { return <div className="color-picker">{palette.map(c => <button key={c} type="button" className={value === c ? 'selected' : ''} style={{ '--swatch': c }} onClick={() => onChange(c)} aria-label={`Color ${c}`} />)}</div> }

function Confirm({ title, text, onCancel, onConfirm, busy }) { return <Modal title={title} kicker="CONFIRMAR ACCIÓN" onClose={onCancel}><p className="modal-copy">{text}</p><div className="modal-actions"><button className="button button-ghost" onClick={onCancel}>Cancelar</button><button className="button button-danger" disabled={busy} onClick={onConfirm}>{busy ? 'Procesando…' : 'Eliminar'}</button></div></Modal> }

function EventForm({ item, selectedDate, calendars, onClose, onSave, busy }) {
  const initial = item?.fecha_inicio || `${selectedDate}T09:00`
  const [form, setForm] = useState({ titulo: item?.titulo || '', descripcion: item?.descripcion || '', fecha: initial.slice(0, 10), fecha_fin: item?.fecha_fin?.slice(0, 10) || initial.slice(0, 10), inicio: timeOf(initial) || '09:00', fin: timeOf(item?.fecha_fin) || '10:00', todo_el_dia: item?.todo_el_dia || false, calendario_id: item?.calendario_id ?? '', se_repite: false, frecuencia: 'semanal', dias: [(parseDate(initial).getDay() + 6) % 7], hasta: '' })
  const set = (key, value) => setForm(f => ({ ...f, [key]: value }))
  const submit = e => {
    e.preventDefault()
    const start = form.todo_el_dia ? form.fecha : `${form.fecha}T${form.inicio}:00`
    const end = form.todo_el_dia ? (form.fecha_fin > form.fecha ? form.fecha_fin : null) : `${form.fecha_fin}T${form.fin}:00`
    if (end && end < start) return alert('La hora de fin debe ser posterior a la de inicio.')
    const payload = { titulo: form.titulo.trim(), descripcion: form.descripcion || null, fecha_inicio: start, fecha_fin: end, todo_el_dia: form.todo_el_dia, calendario_id: form.calendario_id === '' ? null : Number(form.calendario_id) }
    if (!item) { payload.se_repite = form.se_repite; payload.regla_repeticion = form.se_repite ? JSON.stringify({ frecuencia: form.frecuencia, ...(form.frecuencia === 'semanal' ? { dias: form.dias } : {}), ...(form.hasta ? { hasta: form.hasta } : {}) }) : null }
    onSave(payload)
  }
  return <Modal title={item ? 'Editar evento' : 'Nuevo evento'} kicker="TU TIEMPO, EN ORDEN" onClose={onClose}><form onSubmit={submit} className="form"><Field label="Título"><input autoFocus required maxLength="120" value={form.titulo} onChange={e => set('titulo', e.target.value)} placeholder="¿Qué vas a hacer?" /></Field><Field label="Descripción"><textarea rows="2" value={form.descripcion} onChange={e => set('descripcion', e.target.value)} placeholder="Agregá detalles opcionales" /></Field><div className="form-grid"><Field label="Fecha"><input required type="date" value={form.fecha} onChange={e => set('fecha', e.target.value)} /></Field><Field label="Calendario"><select value={form.calendario_id} onChange={e => set('calendario_id', e.target.value)}><option value="">Sin calendario</option>{calendars.map(c => <option key={c.id} value={c.id}>{c.nombre}</option>)}</select></Field></div><Field label="Fecha de fin"><input required type="date" min={form.fecha} value={form.fecha_fin} onChange={e => set('fecha_fin', e.target.value)} /></Field><label className="switch-row"><span>Todo el día</span><input type="checkbox" checked={form.todo_el_dia} onChange={e => set('todo_el_dia', e.target.checked)} /><i /></label>{!form.todo_el_dia && <div className="form-grid"><Field label="Desde"><input type="time" required value={form.inicio} onChange={e => set('inicio', e.target.value)} /></Field><Field label="Hasta"><input type="time" required value={form.fin} onChange={e => set('fin', e.target.value)} /></Field></div>}{!item && <><label className="switch-row"><span>Repetir evento</span><input type="checkbox" checked={form.se_repite} onChange={e => set('se_repite', e.target.checked)} /><i /></label>{form.se_repite && <><div className="form-grid"><Field label="Frecuencia"><select value={form.frecuencia} onChange={e => set('frecuencia', e.target.value)}><option value="diario">Diaria</option><option value="semanal">Semanal</option><option value="mensual">Mensual</option></select></Field><Field label="Repetir hasta (opcional)"><input type="date" min={form.fecha} value={form.hasta} onChange={e => set('hasta', e.target.value)} /></Field></div>{form.frecuencia === 'semanal' && <div className="weekday-picker">{weekdays.map((day, i) => <button type="button" key={day} className={form.dias.includes(i) ? 'active' : ''} onClick={() => set('dias', form.dias.includes(i) ? form.dias.filter(x => x !== i) : [...form.dias, i])}>{day.slice(0, 1)}</button>)}</div>}</>}</>}<div className="modal-actions"><button type="button" className="button button-ghost" onClick={onClose}>Cancelar</button><button className="button button-primary" disabled={busy || !form.titulo.trim() || (form.se_repite && form.frecuencia === 'semanal' && !form.dias.length)}>{busy ? 'Guardando…' : item ? 'Guardar cambios' : 'Crear evento'}</button></div></form></Modal>
}

function TaskForm({ item, selectedDate, lists, onClose, onSave, busy }) {
  const [form, setForm] = useState({ titulo: item?.titulo || '', descripcion: item?.descripcion || '', fecha_opcional: item ? (item.fecha_opcional || '') : selectedDate, hora_opcional: item?.hora_opcional || '', hora_bloque: item?.hora_bloque || '', duracion_estimada: item?.duracion_estimada || '', lista_id: item?.lista_id ?? '', se_repite: false, frecuencia: 'semanal', dias: [(parseDate(selectedDate).getDay() + 6) % 7], hasta: '' })
  const set = (key, value) => setForm(f => ({ ...f, [key]: value }))
  const submit = e => { e.preventDefault(); const payload = { titulo: form.titulo.trim(), descripcion: form.descripcion || null, fecha_opcional: form.fecha_opcional || null, hora_opcional: form.hora_opcional || null, hora_bloque: form.hora_bloque || null, duracion_estimada: form.duracion_estimada ? Number(form.duracion_estimada) : null, lista_id: form.lista_id === '' ? null : Number(form.lista_id) }; if (!item) { payload.se_repite = form.se_repite; payload.regla_repeticion = form.se_repite ? JSON.stringify({ frecuencia: form.frecuencia, ...(form.frecuencia === 'semanal' ? { dias: form.dias } : {}), ...(form.hasta ? { hasta: form.hasta } : {}) }) : null } onSave(payload) }
  return <Modal title={item ? 'Editar tarea' : 'Nueva tarea'} kicker="UNA IDEA, UN PRÓXIMO PASO" onClose={onClose}><form onSubmit={submit} className="form"><Field label="Título"><input autoFocus required maxLength="120" value={form.titulo} onChange={e => set('titulo', e.target.value)} placeholder="¿Qué tenés pendiente?" /></Field><Field label="Descripción"><textarea rows="2" value={form.descripcion} onChange={e => set('descripcion', e.target.value)} placeholder="Notas o contexto" /></Field><div className="form-grid"><Field label="Fecha"><input type="date" value={form.fecha_opcional} onChange={e => set('fecha_opcional', e.target.value)} /></Field><Field label="Lista"><select value={form.lista_id} onChange={e => set('lista_id', e.target.value)}><option value="">Sin lista</option>{lists.map(l => <option key={l.id} value={l.id}>{l.nombre}</option>)}</select></Field></div><div className="form-grid form-grid-3"><Field label="Hora límite"><input type="time" value={form.hora_opcional} onChange={e => set('hora_opcional', e.target.value)} /></Field><Field label="Bloque a las"><input type="time" value={form.hora_bloque} onChange={e => set('hora_bloque', e.target.value)} /></Field><Field label="Duración (min)"><input type="number" min="1" value={form.duracion_estimada} onChange={e => set('duracion_estimada', e.target.value)} /></Field></div>{!item && <><label className="switch-row"><span>Repetir tarea</span><input type="checkbox" checked={form.se_repite} onChange={e => set('se_repite', e.target.checked)} /><i /></label>{form.se_repite && <><div className="form-grid"><Field label="Frecuencia"><select value={form.frecuencia} onChange={e => set('frecuencia', e.target.value)}><option value="diario">Diaria</option><option value="semanal">Semanal</option><option value="mensual">Mensual</option></select></Field><Field label="Repetir hasta"><input type="date" min={form.fecha_opcional} value={form.hasta} onChange={e => set('hasta', e.target.value)} /></Field></div>{form.frecuencia === 'semanal' && <div className="weekday-picker">{weekdays.map((day, i) => <button type="button" key={day} className={form.dias.includes(i) ? 'active' : ''} onClick={() => set('dias', form.dias.includes(i) ? form.dias.filter(x => x !== i) : [...form.dias, i])}>{day.slice(0, 1)}</button>)}</div>}</>}</>}<div className="modal-actions"><button type="button" className="button button-ghost" onClick={onClose}>Cancelar</button><button className="button button-primary" disabled={busy || !form.titulo.trim() || (form.se_repite && !form.fecha_opcional)}>{busy ? 'Guardando…' : item ? 'Guardar cambios' : 'Crear tarea'}</button></div></form></Modal>
}

function CategoryForm({ kind, item, onClose, onSave, busy }) {
  const [name, setName] = useState(item?.nombre || '')
  const [color, setColor] = useState(item?.color || palette[kind === 'calendario' ? 0 : 1])
  return <Modal title={`${item ? 'Editar' : 'Nueva'} ${kind === 'calendario' ? 'calendario' : 'lista'}`} kicker="ORGANIZÁ A TU MANERA" onClose={onClose}><form className="form" onSubmit={e => { e.preventDefault(); onSave({ nombre: name.trim(), color }) }}><Field label="Nombre"><input autoFocus required value={name} onChange={e => setName(e.target.value)} placeholder={kind === 'calendario' ? 'Ej. Trabajo, Personal…' : 'Ej. Proyectos, Compras…'} /></Field><Field label="Color de identificación"><ColorPicker value={color} onChange={setColor} /></Field><div className="modal-actions"><button type="button" className="button button-ghost" onClick={onClose}>Cancelar</button><button className="button button-primary" disabled={busy || !name.trim()}>{busy ? 'Guardando…' : 'Guardar'}</button></div></form></Modal>
}

function ScheduleForm({ item, onClose, onSave, busy }) {
  const [form, setForm] = useState({ dia_semana: item?.dia_semana ?? 0, hora_inicio: item?.hora_inicio || '09:00', hora_fin: item?.hora_fin || '10:30', materia: item?.materia || '', descripcion: item?.descripcion || '', color: item?.color || palette[3] })
  const set = (key, value) => setForm(f => ({ ...f, [key]: value }))
  return <Modal title={item ? 'Editar clase' : 'Nueva clase'} kicker="HORARIO DE FACULTAD" onClose={onClose}><form className="form" onSubmit={e => { e.preventDefault(); if (form.hora_fin <= form.hora_inicio) return alert('La hora de fin debe ser posterior al inicio.'); onSave({ ...form, dia_semana: Number(form.dia_semana) }) }}><Field label="Materia"><input autoFocus required value={form.materia} onChange={e => set('materia', e.target.value)} placeholder="Nombre de la materia" /></Field><div className="form-grid"><Field label="Día"><select value={form.dia_semana} onChange={e => set('dia_semana', e.target.value)}>{weekdays.map((d, i) => <option key={d} value={i}>{d}</option>)}</select></Field><Field label="Descripción"><input value={form.descripcion} onChange={e => set('descripcion', e.target.value)} placeholder="Aula, profesor…" /></Field></div><div className="form-grid"><Field label="Desde"><input required type="time" value={form.hora_inicio} onChange={e => set('hora_inicio', e.target.value)} /></Field><Field label="Hasta"><input required type="time" value={form.hora_fin} onChange={e => set('hora_fin', e.target.value)} /></Field></div><Field label="Color"><ColorPicker value={form.color} onChange={v => set('color', v)} /></Field><div className="modal-actions"><button type="button" className="button button-ghost" onClick={onClose}>Cancelar</button><button className="button button-primary" disabled={busy || !form.materia.trim()}>{busy ? 'Guardando…' : 'Guardar clase'}</button></div></form></Modal>
}

function MiniCalendar({ date, selected, onSelect }) {
  const first = weekStart(startOfMonth(date))
  const days = Array.from({ length: 42 }, (_, i) => addDays(first, i))
  return <div className="mini-calendar"><div className="mini-title"><span>{months[date.getMonth()]} {date.getFullYear()}</span><CalendarDays size={15} /></div><div className="mini-grid">{weekdays.map(d => <b key={d}>{d[0]}</b>)}{days.map(d => <button key={localISO(d)} className={`${d.getMonth() !== date.getMonth() ? 'muted' : ''} ${sameDay(d, new Date()) ? 'today' : ''} ${localISO(d) === selected ? 'selected' : ''}`} onClick={() => onSelect(d)}>{d.getDate()}</button>)}</div></div>
}

function Sidebar({ page, setPage, date, selected, onSelectDate, calendars, lists, filters, toggleFilter, onNewCategory, onSearch, mobileOpen, closeMobile, connected }) {
  const nav = [[LayoutDashboard, 'Resumen', 'resumen'], [CalendarDays, 'Calendario', 'calendario'], [ListTodo, 'Tareas', 'tareas'], [GraduationCap, 'Facultad', 'facultad'], [Activity, 'Revisión', 'revision']]
  return <><div className={`sidebar-scrim ${mobileOpen ? 'show' : ''}`} onClick={closeMobile} /><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><div className="brand"><div className="brand-mark"><span /></div><div><strong>SGR<span className="brand-dot">.</span></strong><small>ESPACIO PERSONAL</small></div></div><div className="sidebar-section-label">WORKSPACE</div><nav className="nav">{nav.map(([Icon, label, id]) => <button key={id} className={page === id ? 'active' : ''} onClick={() => { setPage(id); closeMobile() }}><Icon size={18} strokeWidth={1.8} /><span>{label}</span>{page === id && <i />}</button>)}</nav><button className="sidebar-search" onClick={onSearch}><Search size={16} /><span>Buscar en agenda</span><kbd>⌘ K</kbd></button><MiniCalendar date={date} selected={selected} onSelect={onSelectDate} /><div className="sidebar-list-head"><span>CALENDARIOS</span><IconButton icon={Plus} label="Nuevo calendario" onClick={() => onNewCategory('calendario')} /></div><div className="category-list">{calendars.map(c => <button key={c.id} className={filters.includes(c.id) ? 'muted' : ''} onClick={() => toggleFilter(c.id)}><span className="category-dot" style={{ background: c.color }} /><span>{c.nombre}</span><span className="category-check">{!filters.includes(c.id) && <Check size={13} />}</span></button>)}{!calendars.length && <p className="sidebar-hint">Creá categorías para separar tus eventos.</p>}</div><div className="sidebar-foot"><span className="connection-dot" style={{ background: connected ? undefined : '#ff788f', boxShadow: connected ? undefined : '0 0 10px #ff788f' }} /> {connected ? 'AGENDA CONECTADA' : 'SIN CONEXIÓN'} <span className="foot-line" /></div></aside></>
}

function EventCard({ event, onClick, compact = false }) { return <button className={`event-card ${compact ? 'compact' : ''}`} style={{ '--event': event.calendario_color || palette[0] }} onClick={e => { e.stopPropagation(); onClick(event) }}><span className="event-time">{event.todo_el_dia ? 'DÍA' : timeOf(event.fecha_inicio) || '—'}</span><span className="event-name">{event.titulo}</span>{!compact && <span className="event-category">{event.calendario_nombre || 'Personal'}</span>}</button> }

function MonthView({ date, events, tasks, onDay, onEvent, onTask, onNewEvent }) {
  const first = weekStart(startOfMonth(date))
  const last = addDays(weekStart(endOfMonth(date)), 6)
  const count = Math.round((last - first) / 86400000) + 1
  const days = Array.from({ length: count }, (_, i) => addDays(first, i))
  return <div className="calendar-shell"><div className="month-weekdays">{weekdays.map(d => <span key={d}>{d}</span>)}</div><div className="month-grid">{days.map(d => { const iso = localISO(d); const dayEvents = events.filter(e => e.fecha_inicio?.slice(0, 10) === iso); const dayTasks = tasks.filter(t => t.fecha_opcional === iso && !t.completada); return <div key={iso} className={`month-day ${d.getMonth() !== date.getMonth() ? 'outside' : ''} ${sameDay(d, new Date()) ? 'is-today' : ''}`} onClick={() => onDay(d)}><div className="month-day-top"><span>{d.getDate()}</span><button aria-label={`Crear evento el ${iso}`} onClick={e => { e.stopPropagation(); onNewEvent(iso) }}><Plus size={14} /></button></div><div className="day-items">{dayEvents.slice(0, 3).map(e => <EventCard key={e.id} event={e} compact onClick={x => onEvent(x)} />)}{dayTasks.slice(0, Math.max(0, 3 - dayEvents.length)).map(t => <button className="task-chip" key={t.id} style={{ '--event': t.lista_color || palette[1] }} onClick={e => { e.stopPropagation(); onTask(t) }}><span />{t.titulo}</button>)}{dayEvents.length + dayTasks.length > 3 && <span className="more-count">+{dayEvents.length + dayTasks.length - 3} más</span>}</div></div> })}</div></div>
}

function WeekView({ date, events, tasks, schedule, onEvent, onTask, onNewEvent }) {
  const first = weekStart(date)
  const days = Array.from({ length: 7 }, (_, i) => addDays(first, i))
  return <div className="week-shell"><div className="week-columns">{days.map((d, i) => { const iso = localISO(d); const items = events.filter(e => e.fecha_inicio?.slice(0, 10) === iso).sort((a,b) => a.fecha_inicio.localeCompare(b.fecha_inicio)); const due = tasks.filter(t => t.fecha_opcional === iso && !t.completada); const classes = schedule.filter(h => h.dia_semana === i && !h.excepciones?.includes(iso)); return <div className="week-column" key={iso}><div className={`week-day-title ${sameDay(d, new Date()) ? 'active' : ''}`}><span>{weekdays[i]}</span><b>{d.getDate()}</b></div><button className="week-add" onClick={() => onNewEvent(iso)}><Plus size={15} /> Agregar</button><div className="week-stack">{[...items.map(e => ({ type: 'event', value: e, sort: timeOf(e.fecha_inicio) || '00:00' })), ...classes.map(h => ({ type: 'class', value: h, sort: h.hora_inicio })), ...due.map(t => ({ type: 'task', value: t, sort: t.hora_opcional || '23:59' }))].sort((a,b) => a.sort.localeCompare(b.sort)).map(({ type, value }) => type === 'event' ? <EventCard key={`e${value.id}`} event={value} onClick={onEvent} /> : type === 'class' ? <div key={`c${value.id}`} className="class-card" style={{ '--event': value.color || palette[3] }}><span>{value.hora_inicio} · FACULTAD</span><b>{value.materia}</b></div> : <button key={`t${value.id}`} className="week-task" onClick={() => onTask(value)} style={{ '--event': value.lista_color || palette[1] }}><CheckCircle2 size={15} />{value.titulo}</button>)}</div></div> })}</div></div>
}

function AgendaDetail({ item, type, onClose, onEdit, onDelete, onToggle, onStopSeries }) {
  const isEvent = type === 'event'
  return <Modal title={item.titulo} kicker={isEvent ? 'DETALLE DEL EVENTO' : 'DETALLE DE LA TAREA'} onClose={onClose}><div className="detail"><Tag color={isEvent ? item.calendario_color : item.lista_color}>{isEvent ? item.calendario_nombre || 'Sin calendario' : item.lista_nombre || 'Sin lista'}</Tag><p className="detail-date"><CalendarDays size={18} />{formatDate(isEvent ? item.fecha_inicio : item.fecha_opcional) || 'Sin fecha'}{isEvent ? (item.todo_el_dia ? ' · Todo el día' : ` · ${timeOf(item.fecha_inicio)}${item.fecha_fin ? `–${timeOf(item.fecha_fin)}` : ''}`) : item.hora_opcional ? ` · ${item.hora_opcional}` : ''}</p>{item.descripcion && <p className="detail-description">{item.descripcion}</p>}{!isEvent && item.duracion_estimada && <p className="detail-date"><Clock3 size={17} />Duración estimada: {item.duracion_estimada} min</p>}{item.se_repite && <p className="detail-date"><Repeat2 size={17} />Ocurrencia de una serie{item.serie_activa ? ' activa' : ' detenida'}</p>}{!isEvent && <button className={`button ${item.completada ? 'button-ghost' : 'button-primary'} full`} onClick={onToggle}><Check size={16} />{item.completada ? 'Marcar pendiente' : 'Completar tarea'}</button>}<div className="detail-actions"><button className="button button-ghost" onClick={onEdit}><Edit3 size={16} /> Editar</button>{item.serie_activa && <button className="button button-ghost" onClick={onStopSeries}><Repeat2 size={16} /> Detener serie</button>}<button className="button button-text-danger" onClick={onDelete}><Trash2 size={16} /> Eliminar</button></div></div></Modal>
}

function TaskRow({ task, onToggle, onOpen }) { return <div className={`task-row ${task.completada ? 'done' : ''}`}><button className="task-check" style={{ '--task': task.lista_color || palette[1] }} aria-label={task.completada ? 'Marcar pendiente' : 'Completar tarea'} onClick={() => onToggle(task)}>{task.completada && <Check size={15} />}</button><button className="task-row-main" onClick={() => onOpen(task)}><strong>{task.titulo}</strong><span>{task.descripcion || task.lista_nombre || 'Sin lista'}</span></button><span className="task-row-date">{task.fecha_opcional ? formatDate(task.fecha_opcional, { day: 'numeric', month: 'short' }) : 'Sin fecha'}{task.hora_opcional ? ` · ${task.hora_opcional}` : ''}</span><IconButton icon={ChevronRight} label="Ver tarea" onClick={() => onOpen(task)} /></div> }

function Dashboard({ date, events, tasks, calendars, schedule, onEvent, onTask, onToggle, onNewEvent, onNewTask, setPage }) {
  const today = todayISO()
  const next = localISO(addDays(new Date(), 7))
  const todayEvents = events.filter(e => e.fecha_inicio?.slice(0,10) === today).sort((a,b) => a.fecha_inicio.localeCompare(b.fecha_inicio))
  const todayTasks = tasks.filter(t => !t.completada && (!t.fecha_opcional || t.fecha_opcional <= today)).slice(0, 5)
  const upcoming = events.filter(e => e.fecha_inicio?.slice(0,10) > today && e.fecha_inicio?.slice(0,10) <= next).sort((a,b) => a.fecha_inicio.localeCompare(b.fecha_inicio)).slice(0, 4)
  const pending = tasks.filter(t => !t.completada).length
  const completed = tasks.filter(t => t.completada).length
  const ratio = pending + completed ? Math.round(completed / (pending + completed) * 100) : 0
  return <div className="dashboard"><div className="hero"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><div className="hero-content"><div className="hero-kicker"><span className="pulse-dot" /> TU CENTRO DE CONTROL</div><h1>Tu día, <em>en órbita.</em></h1><p>Todo lo que importa, en el momento indicado.</p><div className="hero-actions"><button className="button button-light" onClick={onNewEvent}><Plus size={17} /> Nuevo evento</button><button className="button button-outline-light" onClick={onNewTask}>Crear tarea <ArrowRight size={16} /></button></div></div><div className="hero-date"><span>{weekdays[(new Date().getDay() + 6) % 7]}</span><strong>{new Date().getDate()}</strong><span>{months[new Date().getMonth()]}</span></div></div><div className="stats"><div className="stat stat-cyan"><span>EVENTOS HOY</span><strong>{todayEvents.length.toString().padStart(2, '0')}</strong><small>en tu agenda</small><CalendarDays size={20} /></div><div className="stat stat-violet"><span>TAREAS PENDIENTES</span><strong>{pending.toString().padStart(2, '0')}</strong><small>próximos pasos</small><ListTodo size={20} /></div><div className="stat stat-orange"><span>PRÓXIMOS 7 DÍAS</span><strong>{upcoming.length.toString().padStart(2, '0')}</strong><small>eventos por venir</small><Activity size={20} /></div><div className="stat stat-green"><span>PROGRESO TOTAL</span><strong>{ratio}<sup>%</sup></strong><small>tareas completadas</small><CheckCircle2 size={20} /></div></div><div className="dashboard-grid"><section className="panel today-panel"><div className="panel-head"><div><span className="eyebrow">FOCO / HOY</span><h2>En tu radar</h2></div><button className="text-action" onClick={() => setPage('calendario')}>Ver calendario <ArrowRight size={16} /></button></div>{todayEvents.length ? <div className="timeline">{todayEvents.map(e => <div className="timeline-row" key={e.id}><span className="timeline-hour">{e.todo_el_dia ? 'TODO EL DÍA' : timeOf(e.fecha_inicio)}</span><span className="timeline-line" style={{ '--event': e.calendario_color }} /><button onClick={() => onEvent(e)}><strong>{e.titulo}</strong><small>{e.calendario_nombre || 'Personal'}{e.fecha_fin && !e.todo_el_dia ? ` · hasta ${timeOf(e.fecha_fin)}` : ''}</small></button></div>)}</div> : <Empty icon={CalendarDays} title="Un día para escribir" description="Todavía no tenés eventos para hoy." action="Agregar evento" onAction={onNewEvent} />}</section><section className="panel tasks-panel"><div className="panel-head"><div><span className="eyebrow">EN MARCHA</span><h2>Lo que sigue</h2></div><button className="text-action" onClick={() => setPage('tareas')}>Todas las tareas <ArrowRight size={16} /></button></div>{todayTasks.length ? <div>{todayTasks.map(t => <TaskRow key={t.id} task={t} onToggle={onToggle} onOpen={onTask} />)}</div> : <Empty icon={CheckCircle2} title="Todo al día" description="No hay tareas pendientes para hoy." action="Crear tarea" onAction={onNewTask} />}</section></div><div className="dashboard-bottom"><section className="panel upcoming-panel"><div className="panel-head"><div><span className="eyebrow">MIRADA ADELANTE</span><h2>Próximos eventos</h2></div></div>{upcoming.length ? <div className="upcoming-list">{upcoming.map(e => <button key={e.id} onClick={() => onEvent(e)}><span className="upcoming-date"><strong>{parseDate(e.fecha_inicio).getDate()}</strong><small>{months[parseDate(e.fecha_inicio).getMonth()].slice(0, 3).toUpperCase()}</small></span><span className="upcoming-marker" style={{ background: e.calendario_color }} /><span className="upcoming-info"><strong>{e.titulo}</strong><small>{e.calendario_nombre || 'Personal'} · {e.todo_el_dia ? 'Todo el día' : timeOf(e.fecha_inicio)}</small></span><ChevronRight size={16} /></button>)}</div> : <p className="panel-empty-text">No hay eventos programados para esta semana.</p>}</section><section className="panel category-panel"><div className="panel-head"><div><span className="eyebrow">EN COLORES</span><h2>Tus espacios</h2></div></div><div className="category-cloud">{calendars.length ? calendars.map(c => <div key={c.id}><span style={{ background: c.color }} />{c.nombre}</div>) : <p className="panel-empty-text">Creá calendarios para ordenar tus planes.</p>}</div><div className="category-decoration"><span /><span /><span /></div></section></div></div>
}

function TasksPage({ tasks, lists, filter, setFilter, onToggle, onTask, onNewTask, onNewList, onEditList, onDeleteList, onPin }) {
  const [showCompleted, setShowCompleted] = useState(false)
  const [query, setQuery] = useState('')
  const filtered = tasks.filter(t => (filter === 'all' || (filter === 'unlisted' ? !t.lista_id : t.lista_id === filter)) && (showCompleted || !t.completada) && `${t.titulo} ${t.descripcion || ''}`.toLowerCase().includes(query.toLowerCase())).sort((a,b) => (a.fecha_opcional || '9999').localeCompare(b.fecha_opcional || '9999'))
  const orderedLists = [...lists].sort((a,b) => Number(b.pinned) - Number(a.pinned))
  return <div className="tasks-layout"><aside className="list-sidebar panel"><div className="list-sidebar-title"><span className="eyebrow">ORGANIZACIÓN</span><h3>Mis listas</h3></div><button className={`list-nav ${filter === 'all' ? 'active' : ''}`} onClick={() => setFilter('all')}><span className="list-nav-icon all"><ListTodo size={16} /></span>Todas las tareas <small>{tasks.length}</small></button><button className={`list-nav ${filter === 'unlisted' ? 'active' : ''}`} onClick={() => setFilter('unlisted')}><span className="list-nav-icon" />Sin lista <small>{tasks.filter(t => !t.lista_id).length}</small></button><div className="list-divider" />{orderedLists.map(l => <div key={l.id} className={`list-nav-wrap ${filter === l.id ? 'active' : ''}`}><button className="list-nav" onClick={() => setFilter(l.id)}><span className="list-nav-icon" style={{ background: l.color }} />{l.nombre}<small>{tasks.filter(t => t.lista_id === l.id).length}</small></button><div className="list-actions"><IconButton icon={l.pinned ? Check : Sparkles} label={l.pinned ? 'Desfijar' : 'Fijar'} onClick={() => onPin(l)} /><IconButton icon={Ellipsis} label="Editar lista" onClick={() => onEditList(l)} /></div></div>)}<button className="new-list-button" onClick={onNewList}><Plus size={16} /> Nueva lista</button>{filter !== 'all' && filter !== 'unlisted' && <button className="delete-list-link" onClick={() => onDeleteList(lists.find(l => l.id === filter))}><Trash2 size={14} /> Eliminar esta lista</button>}</aside><section className="tasks-main panel"><div className="panel-head tasks-main-head"><div><span className="eyebrow">TU PRÓXIMO PASO</span><h2>{filter === 'all' ? 'Todas las tareas' : filter === 'unlisted' ? 'Sin lista' : lists.find(l => l.id === filter)?.nombre || 'Tareas'}</h2><p>{filtered.length} {filtered.length === 1 ? 'tarea' : 'tareas'} a la vista</p></div><button className="button button-primary" onClick={onNewTask}><Plus size={17} /> Nueva tarea</button></div><div className="task-controls"><div className="inline-search"><Search size={17} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar tareas…" /></div><label className="show-completed"><input type="checkbox" checked={showCompleted} onChange={e => setShowCompleted(e.target.checked)} /> Mostrar completadas</label></div>{filtered.length ? <div className="task-list">{filtered.map(t => <TaskRow key={t.id} task={t} onToggle={onToggle} onOpen={onTask} />)}</div> : <Empty icon={CheckCircle2} title={query ? 'No encontramos coincidencias' : 'Lista despejada'} description={query ? 'Probá con otro término.' : 'Agregá una tarea para empezar a organizarte.'} action={!query ? 'Crear tarea' : undefined} onAction={onNewTask} />}</section></div>
}

function FacultyPage({ schedule, onNew, onEdit, onDelete, onException }) {
  const days = weekdays
  const hours = Array.from({ length: 24 }, (_, i) => i)
  return <div className="faculty"><div className="faculty-intro panel"><div><span className="eyebrow">CAMPUS / ORGANIZADO</span><h2>Tu semana académica</h2><p>Un mapa claro de tus clases. Las excepciones te dejan liberar fechas puntuales.</p></div><button className="button button-primary" onClick={onNew}><Plus size={17} /> Nueva clase</button></div><div className="faculty-board panel"><div className="faculty-grid-head"><span>HORA</span>{days.map(d => <span key={d}>{d}</span>)}</div><div className="faculty-grid-body"><div className="faculty-hours">{hours.map(h => <span key={h}>{pad(h)}:00</span>)}</div>{days.map((d,i) => <div className="faculty-day" key={d}>{hours.map(h => <div className="faculty-hour-cell" key={h} />)}{schedule.filter(s => s.dia_semana === i).map(s => { const start = Number(s.hora_inicio.slice(0,2)) + Number(s.hora_inicio.slice(3,5)) / 60; const end = Number(s.hora_fin.slice(0,2)) + Number(s.hora_fin.slice(3,5)) / 60; return <button key={s.id} className="faculty-block" style={{ '--event': s.color || palette[3], top: `${start * 56}px`, height: `${Math.max(56, (end - start) * 56 - 4)}px` }} onClick={() => onEdit(s)}><small>{s.hora_inicio} — {s.hora_fin}</small><strong>{s.materia}</strong><span>{s.descripcion || 'Ver detalles'}</span></button> })}</div>)}</div></div><div className="faculty-list"><div className="panel-head"><div><span className="eyebrow">DETALLES</span><h2>Todas las clases</h2></div></div>{schedule.length ? <div className="schedule-cards">{schedule.map(s => <div className="schedule-card" key={s.id} style={{ '--event': s.color || palette[3] }}><span className="schedule-color" /><div><small>{weekdays[s.dia_semana]} · {s.hora_inicio}–{s.hora_fin}</small><strong>{s.materia}</strong><p>{s.descripcion || 'Sin descripción'}{s.excepciones?.length ? ` · ${s.excepciones.length} excepciones` : ''}</p></div><div className="schedule-actions"><IconButton icon={CalendarDays} label="Agregar excepción" onClick={() => onException(s)} /><IconButton icon={Edit3} label="Editar clase" onClick={() => onEdit(s)} /><IconButton icon={Trash2} label="Eliminar clase" onClick={() => onDelete(s)} /></div></div>)}</div> : <Empty icon={GraduationCap} title="Tu horario empieza acá" description="Agregá tus clases para visualizar la semana." action="Agregar clase" onAction={onNew} />}</div></div>
}

function ReviewPage({ review, events, tasks, date }) {
  const total = (review?.completadas || 0) + (review?.incompletas || 0)
  const percent = total ? Math.round(review.completadas / total * 100) : 0
  const max = Math.max(1, ...(review?.por_calendario || []).map(c => c.minutos))
  return <div className="review"><div className="review-hero panel"><span className="eyebrow">PERSPECTIVA / SEMANAL</span><h2>Cada semana cuenta.</h2><p>Una mirada a cómo usaste tu tiempo y lo que pudiste completar.</p><div className="review-period">Semana del {formatDate(localISO(weekStart(date)))} al {formatDate(localISO(addDays(weekStart(date), 6)))}</div></div><div className="review-cards"><div className="review-card panel"><span>EVENTOS</span><strong>{review?.total_eventos ?? 0}</strong><small>en esta semana</small><CalendarDays size={22} /></div><div className="review-card panel"><span>COMPLETADAS</span><strong>{review?.completadas ?? 0}</strong><small>tareas resueltas</small><CheckCircle2 size={22} /></div><div className="review-card panel"><span>PENDIENTES</span><strong>{review?.incompletas ?? 0}</strong><small>tareas de la semana</small><ListTodo size={22} /></div><div className="review-card panel"><span>VENCIDAS</span><strong>{review?.vencidas ?? 0}</strong><small>anteriores a esta semana</small><Clock3 size={22} /></div></div><div className="review-bottom"><section className="panel progress-panel"><span className="eyebrow">AVANCE</span><h2>Tu progreso</h2><div className="progress-big"><div className="progress-ring" style={{ '--progress': `${percent}%` }}><div><strong>{percent}%</strong><small>completado</small></div></div><p>{total ? `${review.completadas} de ${total} tareas con fecha esta semana.` : 'Todavía no hay tareas con fecha en esta semana.'}</p></div></section><section className="panel distribution-panel"><span className="eyebrow">TIEMPO / CATEGORÍA</span><h2>En qué invertiste tu tiempo</h2>{review?.por_calendario?.length ? <div className="bar-list">{review.por_calendario.map((c,i) => <div className="bar-item" key={`${c.nombre}-${i}`}><div><Tag color={c.color}>{c.nombre}</Tag><span>{Math.round(c.minutos / 60 * 10) / 10} h</span></div><div className="bar-track"><i style={{ width: `${Math.max(2, c.minutos / max * 100)}%`, background: c.color }} /></div></div>)}</div> : <Empty icon={Activity} title="Sin tiempo registrado" description="Los eventos con hora y fin van a aparecer acá." />}</section></div></div>
}

function SearchModal({ onClose, onOpenEvent, onOpenTask }) {
  const [query, setQuery] = useState('')
  const [results, setResults] = useState(null)
  const [loading, setLoading] = useState(false)
  useEffect(() => { if (!query.trim()) { setResults(null); return }; let active = true; const timer = setTimeout(() => { setLoading(true); api(`/buscar?q=${encodeURIComponent(query.trim())}`).then(r => { if (active) setResults(r) }).catch(() => { if (active) setResults({ eventos: [], tareas: [] }) }).finally(() => { if (active) setLoading(false) }) }, 250); return () => { active = false; clearTimeout(timer) } }, [query])
  return <Modal title="Buscar en agenda" kicker="ENCONTRÁ LO QUE NECESITÁS" onClose={onClose}><div className="search-modal-input"><Search size={21} /><input autoFocus value={query} onChange={e => setQuery(e.target.value)} placeholder="Eventos, tareas, detalles…" /><kbd>ESC</kbd></div><div className="search-results">{loading && <p className="search-prompt">Buscando…</p>}{!query && <p className="search-prompt">Escribí para explorar toda tu agenda.</p>}{results && !loading && <>{!results.eventos?.length && !results.tareas?.length ? <Empty icon={Search} title="Sin resultados" description="Probá con otras palabras." /> : <>{results.eventos?.length > 0 && <><span className="eyebrow">EVENTOS</span>{results.eventos.map(e => <button key={e.id} onClick={() => onOpenEvent(e)}><span className="search-dot" style={{ background: e.calendario_color }} /><strong>{e.titulo}</strong><small>{formatDate(e.fecha_inicio)}</small></button>)}</>}{results.tareas?.length > 0 && <><span className="eyebrow">TAREAS</span>{results.tareas.map(t => <button key={t.id} onClick={() => onOpenTask(t)}><span className="search-dot" style={{ background: t.lista_color }} /><strong>{t.titulo}</strong><small>{formatDate(t.fecha_opcional) || 'Sin fecha'}</small></button>)}</>}</>}</>}</div></Modal>
}

function ManageModal({ calendars, lists, onClose, onAdd, onEdit, onDelete, onPin }) {
  return <Modal title="Organizar espacios" kicker="PERSONALIZÁ TU AGENDA" onClose={onClose} wide><div className="manage-grid"><section><div className="manage-head"><h3>Calendarios</h3><IconButton icon={Plus} label="Nuevo calendario" onClick={() => onAdd('calendario')} /></div><p>Separá tus eventos por contexto y color.</p>{calendars.map(c => <div className="manage-row" key={c.id}><span className="category-dot" style={{ background: c.color }} /><strong>{c.nombre}</strong><IconButton icon={Edit3} label="Editar calendario" onClick={() => onEdit('calendario', c)} /><IconButton icon={Trash2} label="Eliminar calendario" onClick={() => onDelete('calendario', c)} /></div>)}</section><section><div className="manage-head"><h3>Listas</h3><IconButton icon={Plus} label="Nueva lista" onClick={() => onAdd('lista')} /></div><p>Creá recorridos para tus tareas.</p>{lists.map(l => <div className="manage-row" key={l.id}><span className="category-dot" style={{ background: l.color }} /><strong>{l.nombre}</strong><IconButton icon={l.pinned ? Check : Sparkles} label={l.pinned ? 'Desfijar lista' : 'Fijar lista'} onClick={() => onPin(l)} /><IconButton icon={Edit3} label="Editar lista" onClick={() => onEdit('lista', l)} /><IconButton icon={Trash2} label="Eliminar lista" onClick={() => onDelete('lista', l)} /></div>)}</section></div></Modal>
}

function App() {
  const [page, setPage] = useState('resumen')
  const [view, setView] = useState('mes')
  const [date, setDate] = useState(new Date())
  const [selected, setSelected] = useState(todayISO())
  const [calendars, setCalendars] = useState([])
  const [lists, setLists] = useState([])
  const [events, setEvents] = useState([])
  const [tasks, setTasks] = useState([])
  const [schedule, setSchedule] = useState([])
  const [review, setReview] = useState(null)
  const [notifications, setNotifications] = useState([])
  const [filters, setFilters] = useState([])
  const [taskFilter, setTaskFilter] = useState('all')
  const [modal, setModal] = useState(null)
  const [busy, setBusy] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [toast, setToast] = useState('')
  const [mobileOpen, setMobileOpen] = useState(false)
  const [showNotifications, setShowNotifications] = useState(false)
  const range = useMemo(() => ({ from: localISO(addDays(startOfMonth(date), -14)), to: localISO(addDays(endOfMonth(date), 21)) }), [date.getFullYear(), date.getMonth()])
  const week = useMemo(() => { const start = weekStart(date); return { from: localISO(start), to: localISO(addDays(start, 6)) } }, [date.getFullYear(), date.getMonth(), date.getDate()])
  const refresh = useCallback(async () => {
    try {
      const [c, l, e, t, s, r] = await Promise.all([
        api('/calendarios'), api('/listas'), api(`/eventos?desde=${range.from}&hasta=${range.to}`), api(`/tareas?hasta=${range.to}`), api('/horario-facultad'), api(`/revision?desde=${week.from}&hasta=${week.to}`)
      ])
      setCalendars(c); setLists(l); setEvents(e); setTasks(t); setSchedule(s); setReview(r); setError('')
    } catch (err) { setError(`No pudimos conectar con la API de Agenda. ${err.message}`) }
    finally { setLoading(false) }
  }, [range.from, range.to, week.from, week.to])
  useEffect(() => { refresh() }, [refresh])
  useEffect(() => { const load = () => api('/notificaciones/pending?ventana_min=30').then(setNotifications).catch(() => {}); load(); const id = setInterval(load, 60000); return () => clearInterval(id) }, [])
  useEffect(() => { if (!toast) return; const id = setTimeout(() => setToast(''), 4200); return () => clearTimeout(id) }, [toast])
  useEffect(() => { const handler = e => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setModal({ type: 'search' }) } }; window.addEventListener('keydown', handler); return () => window.removeEventListener('keydown', handler) }, [])
  const run = async (action, message) => { setBusy(true); try { await action(); setModal(null); setToast(message); await refresh() } catch (err) { setToast(`Error: ${err.message}`) } finally { setBusy(false) } }
  const openEvent = item => setModal({ type: 'detail', kind: 'event', item })
  const openTask = item => setModal({ type: 'detail', kind: 'task', item })
  const newEvent = day => { setSelected(day || selected); setModal({ type: 'event', item: null, date: day || selected }) }
  const newTask = () => setModal({ type: 'task', item: null, date: selected })
  const editCategory = (kind, item = null) => setModal({ type: 'category', kind, item })
  const removeCategory = (kind, item) => setModal({ type: 'confirm', title: `Eliminar ${kind}`, text: kind === 'lista' ? `Se eliminará “${item.nombre}” y todas sus tareas. Esta acción no se puede deshacer.` : `Se eliminará “${item.nombre}” y sus eventos asociados. Esta acción no se puede deshacer.`, action: () => mutation(kind === 'lista' ? `/listas/${item.id}` : `/calendarios/${item.id}`, 'DELETE'), after: () => { if (taskFilter === item.id) setTaskFilter('all') } })
  const toggleTask = item => run(() => mutation(`/tareas/${item.id}`, 'PATCH', { completada: !item.completada }), item.completada ? 'Tarea marcada como pendiente' : '¡Tarea completada!')
  const navigate = direction => { const d = new Date(date); if ((page === 'calendario' && view === 'semana') || page === 'revision') d.setDate(d.getDate() + direction * 7); else { d.setDate(1); d.setMonth(d.getMonth() + direction) } setDate(d); setSelected(localISO(d)) }
  const visibleEvents = events.filter(e => !filters.includes(e.calendario_id))
  const pageNames = { resumen: 'Resumen', calendario: 'Calendario', tareas: 'Tareas', facultad: 'Facultad', revision: 'Revisión' }
  return <div className="app"><Sidebar page={page} setPage={setPage} date={date} selected={selected} onSelectDate={d => { setDate(d); setSelected(localISO(d)); setPage('calendario'); setMobileOpen(false) }} calendars={calendars} lists={lists} filters={filters} toggleFilter={id => setFilters(f => f.includes(id) ? f.filter(x => x !== id) : [...f, id])} onNewCategory={kind => editCategory(kind)} onSearch={() => setModal({ type: 'search' })} mobileOpen={mobileOpen} closeMobile={() => setMobileOpen(false)} connected={!error} /><main className="main"><header className="topbar"><div className="topbar-left"><IconButton icon={Menu} label="Abrir menú" className="mobile-menu" onClick={() => setMobileOpen(true)} /><div className="breadcrumb">WORKSPACE <span>/</span> <strong>AGENDA</strong> <span>/</span> {pageNames[page]}</div></div><div className="topbar-actions"><span className="today-indicator"><span /> {formatDate(todayISO(), { weekday: 'long', day: 'numeric', month: 'long' })}</span><IconButton icon={Search} label="Buscar" onClick={() => setModal({ type: 'search' })} /><div className="notifications-wrap"><IconButton icon={Bell} label="Notificaciones" onClick={() => setShowNotifications(x => !x)} />{notifications.length > 0 && <i className="notification-count">{notifications.length}</i>}{showNotifications && <div className="notification-popover"><span className="eyebrow">PRÓXIMOS 30 MINUTOS</span>{notifications.length ? notifications.map(n => <button key={n.id} onClick={() => { setShowNotifications(false); openEvent(n) }}><span className="category-dot" style={{ background: n.calendario_color }} /><strong>{n.titulo}</strong><small>{timeOf(n.fecha_inicio)}</small></button>) : <p>Sin eventos próximos.</p>}</div>}</div><IconButton icon={Settings2} label="Organizar espacios" onClick={() => setModal({ type: 'manage' })} /></div></header><div className="content"><div className="page-heading"><div><span className="eyebrow">{page === 'resumen' ? 'BIENVENIDO A TU ESPACIO' : `AGENDA / ${pageNames[page].toUpperCase()}`}</span><h1>{page === 'resumen' ? 'Buen día.' : page === 'calendario' ? 'Tu calendario.' : page === 'tareas' ? 'Hacé que pase.' : page === 'facultad' ? 'Modo campus.' : 'Mirar hacia atrás.'}</h1><p>{page === 'resumen' ? 'Un panorama claro para empezar con intención.' : page === 'calendario' ? 'Cada plan tiene su lugar.' : page === 'tareas' ? 'Las grandes cosas empiezan por una tarea.' : page === 'facultad' ? 'Todas tus clases, en un solo lugar.' : 'Encontrá patrones en tu semana.'}</p></div>{page === 'calendario' && <button className="button button-primary" onClick={() => newEvent()}><Plus size={17} /> Nuevo evento</button>}{page === 'revision' && <button className="button button-ghost" onClick={() => { setDate(new Date()); setSelected(todayISO()) }}>Esta semana</button>}</div>{error && <div className="error-banner"><span>{error}</span><button onClick={refresh}>Reintentar</button></div>}{loading && <div className="loading-screen"><span className="loading-orbit" /> Sincronizando agenda…</div>}{!loading && !error && <>{page === 'resumen' && <Dashboard date={date} events={visibleEvents} tasks={tasks} calendars={calendars} schedule={schedule} onEvent={openEvent} onTask={openTask} onToggle={toggleTask} onNewEvent={() => newEvent(todayISO())} onNewTask={newTask} setPage={setPage} />}{page === 'calendario' && <><div className="calendar-toolbar"><div className="period-controls"><button className="button button-ghost" onClick={() => { setDate(new Date()); setSelected(todayISO()) }}>Hoy</button><IconButton icon={ChevronLeft} label="Anterior" onClick={() => navigate(-1)} /><IconButton icon={ChevronRight} label="Siguiente" onClick={() => navigate(1)} /><h2>{view === 'mes' ? `${months[date.getMonth()]} ${date.getFullYear()}` : `${formatDate(week.from, { day: 'numeric', month: 'short' })} — ${formatDate(week.to, { day: 'numeric', month: 'short', year: 'numeric' })}`}</h2></div><div className="view-toggle"><button className={view === 'mes' ? 'active' : ''} onClick={() => setView('mes')}>Mes</button><button className={view === 'semana' ? 'active' : ''} onClick={() => setView('semana')}>Semana</button></div><a className="button button-ghost export-button" href={`/agenda/export.ics?desde=${range.from}&hasta=${range.to}`} download><ArrowDownToLine size={16} /> Exportar .ics</a></div>{view === 'mes' ? <MonthView date={date} events={visibleEvents} tasks={tasks} onDay={d => { setDate(d); setSelected(localISO(d)); setView('semana') }} onEvent={openEvent} onTask={openTask} onNewEvent={newEvent} /> : <WeekView date={date} events={visibleEvents} tasks={tasks} schedule={schedule} onEvent={openEvent} onTask={openTask} onNewEvent={newEvent} />}</>}{page === 'tareas' && <TasksPage tasks={tasks} lists={lists} filter={taskFilter} setFilter={setTaskFilter} onToggle={toggleTask} onTask={openTask} onNewTask={newTask} onNewList={() => editCategory('lista')} onEditList={l => editCategory('lista', l)} onDeleteList={l => removeCategory('lista', l)} onPin={l => run(() => mutation(`/listas/${l.id}`, 'PATCH', { pinned: !l.pinned }), l.pinned ? 'Lista desfijada' : 'Lista fijada')} />}{page === 'facultad' && <FacultyPage schedule={schedule} onNew={() => setModal({ type: 'schedule' })} onEdit={item => setModal({ type: 'schedule', item })} onDelete={item => setModal({ type: 'confirm', title: 'Eliminar clase', text: `Se eliminará “${item.materia}” de tu horario semanal.`, action: () => mutation(`/horario-facultad/${item.id}`, 'DELETE') })} onException={item => setModal({ type: 'exception', item })} />}{page === 'revision' && <><div className="review-navigation"><IconButton icon={ChevronLeft} label="Semana anterior" onClick={() => navigate(-1)} /><span>{formatDate(week.from)} — {formatDate(week.to)}</span><IconButton icon={ChevronRight} label="Semana siguiente" onClick={() => navigate(1)} /></div><ReviewPage review={review} events={events} tasks={tasks} date={date} /></>}</>}</div></main>{toast && <div className="toast" role="status"><Sparkles size={17} />{toast}<button onClick={() => setToast('')}><X size={15} /></button></div>}
    {modal?.type === 'event' && <EventForm item={modal.item} selectedDate={modal.date || selected} calendars={calendars} busy={busy} onClose={() => setModal(null)} onSave={body => run(() => mutation(modal.item ? `/eventos/${modal.item.id}` : '/eventos', modal.item ? 'PATCH' : 'POST', body), modal.item ? 'Evento actualizado' : 'Evento creado')} />}
    {modal?.type === 'task' && <TaskForm item={modal.item} selectedDate={modal.date || selected} lists={lists} busy={busy} onClose={() => setModal(null)} onSave={body => run(() => mutation(modal.item ? `/tareas/${modal.item.id}` : '/tareas', modal.item ? 'PATCH' : 'POST', body), modal.item ? 'Tarea actualizada' : 'Tarea creada')} />}
    {modal?.type === 'category' && <CategoryForm kind={modal.kind} item={modal.item} busy={busy} onClose={() => setModal(null)} onSave={body => run(() => mutation(modal.kind === 'calendario' ? `/calendarios${modal.item ? `/${modal.item.id}` : ''}` : `/listas${modal.item ? `/${modal.item.id}` : ''}`, modal.item ? 'PATCH' : 'POST', body), modal.item ? 'Categoría actualizada' : 'Categoría creada')} />}
    {modal?.type === 'schedule' && <ScheduleForm item={modal.item} busy={busy} onClose={() => setModal(null)} onSave={body => run(() => mutation(`/horario-facultad${modal.item ? `/${modal.item.id}` : ''}`, modal.item ? 'PATCH' : 'POST', body), modal.item ? 'Clase actualizada' : 'Clase agregada')} />}
    {modal?.type === 'detail' && <AgendaDetail item={modal.item} type={modal.kind} onClose={() => setModal(null)} onEdit={() => setModal({ type: modal.kind === 'event' ? 'event' : 'task', item: modal.item })} onToggle={() => toggleTask(modal.item)} onDelete={() => setModal({ type: 'confirm', title: `Eliminar ${modal.kind === 'event' ? 'evento' : 'tarea'}`, text: `Se eliminará “${modal.item.titulo}”. Esta acción no se puede deshacer.`, action: () => mutation(modal.kind === 'event' ? `/eventos/${modal.item.id}` : `/tareas/${modal.item.id}`, 'DELETE') })} onStopSeries={() => setModal({ type: 'confirm', title: 'Detener repetición', text: 'No se crearán más ocurrencias futuras. Las existentes permanecerán.', action: () => mutation(`/series/${modal.kind === 'event' ? 'evento' : 'tarea'}/${modal.item.serie_id || modal.item.id}`, 'DELETE'), button: 'Detener serie' })} />}
    {modal?.type === 'confirm' && <Confirm title={modal.title} text={modal.text} busy={busy} onCancel={() => setModal(null)} onConfirm={() => run(async () => { await modal.action(); modal.after?.() }, 'Cambio guardado')} />}
    {modal?.type === 'search' && <SearchModal onClose={() => setModal(null)} onOpenEvent={openEvent} onOpenTask={openTask} />}
    {modal?.type === 'manage' && <ManageModal calendars={calendars} lists={lists} onClose={() => setModal(null)} onAdd={kind => editCategory(kind)} onEdit={editCategory} onDelete={removeCategory} onPin={l => run(() => mutation(`/listas/${l.id}`, 'PATCH', { pinned: !l.pinned }), 'Lista actualizada')} />}
    {modal?.type === 'exception' && <ExceptionModal item={modal.item} busy={busy} onClose={() => setModal(null)} onSave={fecha => run(() => mutation(`/horario-facultad/${modal.item.id}/excepciones`, 'POST', { fecha }), 'Excepción agregada')} />}
  </div>
}

function ExceptionModal({ item, onClose, onSave, busy }) { const [fecha, setFecha] = useState(todayISO()); return <Modal title="Liberar una clase" kicker="EXCEPCIÓN / FACULTAD" onClose={onClose}><form className="form" onSubmit={e => { e.preventDefault(); onSave(fecha) }}><p className="modal-copy">“{item.materia}” no aparecerá en la agenda semanal para esta fecha.</p><Field label="Fecha de la excepción"><input type="date" required value={fecha} onChange={e => setFecha(e.target.value)} /></Field><div className="modal-actions"><button type="button" className="button button-ghost" onClick={onClose}>Cancelar</button><button className="button button-primary" disabled={busy || item.excepciones?.includes(fecha)}>{busy ? 'Guardando…' : 'Guardar excepción'}</button></div></form></Modal> }

createRoot(document.getElementById('root')).render(<App />)
